        if col==bg or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        while q:
          y,x=q.pop(); comp.append((y,x))
          for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
            if 0<=yy<h and 0<=xx<w and grid[yy][xx]==col and (yy,xx) not in seen: seen.add((yy,xx)); q.append((yy,xx))
        # use a nearby singleton color as the replacement, if present
        if len(comp)>1:
          singles=[]
          for y in range(h):
            for x in range(w):
              if grid[y][x]!=bg and sum(1 for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)) if 0<=yy<h and 0<=xx<w and grid[yy][xx]==grid[y][x])==0:
                singles.append((y,x,grid[y][x]))
          if singles:
            d=min(abs(y-a)+abs(x-b) for y,x in comp for a,b,_ in singles)
            close=[(a,b,k) for a,b,k in singles if min(abs(y-a)+abs(x-b) for y,x in comp)==d]
            if close:
              nc=close[0][2]
              if d==1:
                for y,x in comp: out[y][x]=nc
    return out
''')
